import type {
  LabAssessmentQuestion,
  LabVocabularyItem,
  SourceProvenance,
  UnitFourSkillsContent,
} from '../../types/interactiveLab';

type RawWord = [
  word: string,
  ipaUk: string,
  pos: string,
  meaningVi: string,
  example: string,
  contextNote: string,
  provenance?: SourceProvenance,
  ipaUs?: string,
];

function buildVocab(unitId: string, rows: RawWord[]): LabVocabularyItem[] {
  return rows.map(([word, ipaUk, partOfSpeech, meaningVi, example, contextNote, provenance, ipaUs], idx) => ({
    id: `${unitId}-v${String(idx + 1).padStart(2, '0')}`,
    unitId,
    word,
    ipaUk,
    ipaUs,
    partOfSpeech,
    meaningVi,
    example,
    contextNote,
    provenance: provenance ?? 'textbook_reference',
  }));
}

function qMcq(
  id: string,
  unitId: string,
  skill: 'listening' | 'reading',
  prompt: string,
  options: [string, string, string, string],
  correct: 'A' | 'B' | 'C' | 'D',
  explanationVi: string,
  learningOutcome: string,
): LabAssessmentQuestion {
  const labels = ['A', 'B', 'C', 'D'] as const;
  return {
    id,
    unitId,
    grade: 11,
    skill,
    cognitiveLevel: skill === 'listening' ? 'comprehension' : 'application',
    format: 'mcq',
    prompt,
    options: options.map((text, i) => ({label: labels[i], text})),
    correctAnswer: correct,
    explanationVi,
    learningOutcome,
    points: 0.25,
    sourceLabel: `Interactive Lab · Global Success 11 (${unitId.toUpperCase()})`,
  };
}

